export type GpsCoordinates = {
  latitude: number;
  longitude: number;
  accuracyMeters?: number;
  capturedAt?: string;
  source?: 'browser_geolocation' | 'manual' | 'exif';
};

export type GeolocationCaptureResult =
  | { ok: true; coords: GpsCoordinates }
  | { ok: false; error: string; code?: string };

const isBrowser = typeof window !== 'undefined' && typeof navigator !== 'undefined';

export const getCurrentGpsCoordinates = (options?: {
  enableHighAccuracy?: boolean;
  timeoutMs?: number;
}): Promise<GeolocationCaptureResult> => {
  if (!isBrowser) {
    return Promise.resolve({ ok: false, error: 'Geolocation is only available in the browser.' });
  }

  if (!navigator.geolocation) {
    return Promise.resolve({
      ok: false,
      error: 'This device or browser does not support GPS location capture.',
      code: 'unsupported',
    });
  }

  const timeoutMs = options?.timeoutMs ?? 15000;

  return new Promise((resolve) => {
    navigator.geolocation.getCurrentPosition(
      (position) => {
        resolve({
          ok: true,
          coords: {
            latitude: position.coords.latitude,
            longitude: position.coords.longitude,
            accuracyMeters: position.coords.accuracy,
            capturedAt: new Date().toISOString(),
            source: 'browser_geolocation',
          },
        });
      },
      (error) => {
        const messageByCode: Record<number, string> = {
          1: 'Location permission denied. Allow location for this site in your browser settings, then tap Retry GPS. You can still upload a site photo without GPS (weaker evidence).',
          2: 'Location unavailable. Move outdoors with clear sky view and try again, or upload the photo without GPS.',
          3: 'Location request timed out. Retry GPS, or upload the photo without GPS if needed.',
        };
        resolve({
          ok: false,
          error: messageByCode[error.code] || error.message || 'Failed to capture GPS coordinates.',
          code: String(error.code),
        });
      },
      {
        enableHighAccuracy: options?.enableHighAccuracy !== false,
        timeout: timeoutMs,
        maximumAge: 0,
      }
    );
  });
};

export const formatGpsLabel = (coords?: GpsCoordinates | null): string => {
  if (!coords) return 'No GPS captured';
  return `${coords.latitude.toFixed(6)}, ${coords.longitude.toFixed(6)}`;
};

export const buildMapsLink = (coords?: GpsCoordinates | null): string | null => {
  if (!coords) return null;
  return `https://www.google.com/maps?q=${coords.latitude},${coords.longitude}`;
};

export const parseManualGps = (
  latitude: string | number,
  longitude: string | number
): GpsCoordinates | null => {
  const lat = Number(latitude);
  const lon = Number(longitude);
  if (!Number.isFinite(lat) || !Number.isFinite(lon)) return null;
  if (Math.abs(lat) > 90 || Math.abs(lon) > 180) return null;
  return {
    latitude: lat,
    longitude: lon,
    capturedAt: new Date().toISOString(),
    source: 'manual',
  };
};

export const isImageFile = (file: File): boolean => {
  const mime = (file.type || '').toLowerCase();
  if (mime.startsWith('image/')) return true;
  return /\.(jpe?g|png|webp|heic|heif)$/i.test(file.name || '');
};
