import React, { useEffect, useMemo } from 'react';
import {
  Box,
  Breadcrumbs,
  Chip,
  FormControl,
  InputLabel,
  Link,
  MenuItem,
  Select,
  Tab,
  Tabs,
  Typography,
} from '@mui/material';
import { Link as RouterLink } from 'react-router-dom';
import {
  COMPLIANCE_PERIODS,
  ComplianceSectionGroup,
  ComplianceTrackPath,
  findComplianceSectionGroup,
} from '../../constants/complianceHub';

interface ComplianceTrackShellProps {
  trackTitle: string;
  trackDescription: string;
  trackPath: ComplianceTrackPath;
  sectionGroups: ComplianceSectionGroup[];
  activeSection: string;
  onSectionChange: (sectionId: string) => void;
  period: string;
  onPeriodChange: (period: string) => void;
  loading?: boolean;
  children: React.ReactNode;
}

const ComplianceTrackShell: React.FC<ComplianceTrackShellProps> = ({
  trackTitle,
  trackDescription,
  trackPath: _trackPath,
  sectionGroups,
  activeSection,
  onSectionChange,
  period,
  onPeriodChange,
  loading,
  children,
}) => {
  const activeGroup = useMemo(
    () => findComplianceSectionGroup(sectionGroups, activeSection) ?? sectionGroups[0],
    [sectionGroups, activeSection]
  );

  const groupIndex = Math.max(
    0,
    sectionGroups.findIndex((group) => group.id === activeGroup.id)
  );

  const sectionIndex = Math.max(
    0,
    activeGroup.sections.findIndex((section) => section.id === activeSection)
  );

  const activeSectionDef =
    activeGroup.sections.find((section) => section.id === activeSection) ??
    activeGroup.sections[sectionIndex] ??
    activeGroup.sections[0];

  useEffect(() => {
    if (!activeGroup.sections.some((section) => section.id === activeSection)) {
      onSectionChange(activeGroup.sections[0]?.id ?? 'overview');
    }
  }, [activeGroup, activeSection, onSectionChange]);

  const handleGroupChange = (_: React.SyntheticEvent, idx: number) => {
    const nextGroup = sectionGroups[idx];
    if (!nextGroup) {
      return;
    }
    const currentSectionStillInGroup = nextGroup.sections.some((section) => section.id === activeSection);
    onSectionChange(
      currentSectionStillInGroup ? activeSection : nextGroup.sections[0]?.id ?? 'overview'
    );
  };

  const handleSectionChange = (_: React.SyntheticEvent, idx: number) => {
    onSectionChange(activeGroup.sections[idx]?.id ?? activeGroup.sections[0]?.id ?? 'overview');
  };

  return (
    <Box>
      <Breadcrumbs sx={{ mb: 2 }} aria-label="Compliance navigation">
        <Link component={RouterLink} to="/compliance" underline="hover" color="inherit">
          Compliance
        </Link>
        <Typography
          component="h1"
          variant="body1"
          color="text.primary"
          sx={{ m: 0, fontWeight: 400, fontSize: 'inherit', lineHeight: 'inherit' }}
        >
          {trackTitle}
        </Typography>
      </Breadcrumbs>

      <Box
        sx={{
          display: 'flex',
          flexDirection: { xs: 'column', md: 'row' },
          alignItems: { xs: 'stretch', md: 'flex-start' },
          justifyContent: 'space-between',
          gap: 2,
          mb: 2,
        }}
      >
        <Box sx={{ flex: 1, minWidth: 0 }}>
          <Typography variant="body1" color="text.secondary">
            {trackDescription}
          </Typography>
        </Box>
        <FormControl size="small" sx={{ minWidth: 180 }}>
          <InputLabel id="compliance-period-label">Reporting period</InputLabel>
          <Select
            labelId="compliance-period-label"
            label="Reporting period"
            value={period}
            onChange={(e) => onPeriodChange(e.target.value)}
          >
            {COMPLIANCE_PERIODS.map((p) => (
              <MenuItem key={p.value} value={p.value}>
                {p.label}
              </MenuItem>
            ))}
          </Select>
        </FormControl>
      </Box>

      <Tabs
        value={groupIndex}
        onChange={handleGroupChange}
        variant="scrollable"
        scrollButtons="auto"
        sx={{ mb: activeGroup.sections.length > 1 ? 1 : 2, borderBottom: 1, borderColor: 'divider' }}
        aria-label={`${trackTitle} section groups`}
      >
        {sectionGroups.map((group) => (
          <Tab key={group.id} label={group.label} />
        ))}
      </Tabs>

      {activeGroup.sections.length > 1 ? (
        <Tabs
          value={sectionIndex}
          onChange={handleSectionChange}
          variant="scrollable"
          scrollButtons="auto"
          sx={{ mb: 2, borderBottom: 1, borderColor: 'divider' }}
          aria-label={`${activeGroup.label} workflows`}
        >
          {activeGroup.sections.map((section) => (
            <Tab key={section.id} label={section.label} />
          ))}
        </Tabs>
      ) : null}

      {loading ? (
        <Chip label="Loading compliance data…" color="info" sx={{ mb: 2 }} />
      ) : null}

      <Typography variant="subtitle2" color="text.secondary" sx={{ mb: 2 }}>
        {activeSectionDef?.description}
      </Typography>

      {children}
    </Box>
  );
};

export default ComplianceTrackShell;
