import { useCallback, useMemo } from 'react';
import { useSearchParams } from 'react-router-dom';
import { normalizeComplianceSectionId } from '../constants/complianceHub';

/**
 * Keeps in-page section state in sync with the `?section=` query param for sidebar deep links.
 * When `validSections` is omitted, any section value from the URL is accepted.
 */
export function useUrlSectionParam(
  defaultSection = '',
  validSections?: readonly string[]
): [string, (section: string) => void] {
  const [searchParams, setSearchParams] = useSearchParams();

  const section = useMemo(() => {
    const raw = searchParams.get('section');
    if (raw === null || raw === '') {
      return defaultSection;
    }
    if (validSections && validSections.length > 0) {
      const normalized = normalizeComplianceSectionId(raw, validSections);
      return normalized ?? defaultSection;
    }
    return raw;
  }, [searchParams, defaultSection, validSections]);

  const setSection = useCallback(
    (value: string) => {
      setSearchParams(
        (prev) => {
          const next = new URLSearchParams(prev);
          next.delete('tab');
          if (value === defaultSection || value === '') {
            next.delete('section');
          } else {
            next.set('section', value);
          }
          return next;
        },
        { replace: true }
      );
    },
    [setSearchParams, defaultSection]
  );

  return [section, setSection];
}
