export type GeotaggedEvidenceWorkflow =
  | 'cbam_installation_boundary'
  | 'eudr_plot_evidence'
  | 'iso_site_evidence'
  | 'pat_facility_evidence'
  | 'general_compliance_evidence';

export type GeotaggedWorkflowConfig = {
  id: GeotaggedEvidenceWorkflow;
  label: string;
  description: string;
  purposeLabel: string;
  notesTemplate: string;
  reportingFrameworks: string[];
};

export const GEOTAGGED_EVIDENCE_WORKFLOWS: GeotaggedWorkflowConfig[] = [
  {
    id: 'cbam_installation_boundary',
    label: 'CBAM installation site',
    description: 'EU CBAM installation boundary — factory or production unit identity',
    purposeLabel: 'CBAM installation site evidence',
    notesTemplate: 'CBAM installation site photo — auto GPS geotagged boundary evidence',
    reportingFrameworks: ['EU CBAM'],
  },
  {
    id: 'eudr_plot_evidence',
    label: 'EUDR supplier plot',
    description: 'EU Deforestation Regulation plot-level geolocation for commodities',
    purposeLabel: 'EUDR supplier plot geolocation',
    notesTemplate: 'EUDR supplier plot photo — auto GPS geotagged plot evidence',
    reportingFrameworks: ['EUDR'],
  },
  {
    id: 'iso_site_evidence',
    label: 'ISO site verification',
    description: 'ISO 14064 / 14067 organizational or product system boundary site proof',
    purposeLabel: 'ISO site boundary evidence',
    notesTemplate: 'ISO site verification photo — auto GPS geotagged facility evidence',
    reportingFrameworks: ['ISO 14064', 'ISO 14067'],
  },
  {
    id: 'pat_facility_evidence',
    label: 'PAT facility boundary',
    description: 'Perform, Achieve and Trade designated consumer facility location proof',
    purposeLabel: 'PAT facility boundary evidence',
    notesTemplate: 'PAT facility site photo — auto GPS geotagged boundary evidence',
    reportingFrameworks: ['PAT / BEE India'],
  },
  {
    id: 'general_compliance_evidence',
    label: 'General compliance site',
    description: 'Buyer audit or compliance hub site evidence with automatic geolocation',
    purposeLabel: 'Compliance site evidence',
    notesTemplate: 'Compliance site photo — auto GPS geotagged evidence',
    reportingFrameworks: ['Compliance Hub'],
  },
];

export const getGeotaggedWorkflowConfig = (
  workflow: GeotaggedEvidenceWorkflow
): GeotaggedWorkflowConfig =>
  GEOTAGGED_EVIDENCE_WORKFLOWS.find((entry) => entry.id === workflow)
  || GEOTAGGED_EVIDENCE_WORKFLOWS[GEOTAGGED_EVIDENCE_WORKFLOWS.length - 1];
